        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        """
        if not self.is_valid_input(textnum):
            return "Invalid input"
        return self._text2int(textnum)

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        """
        # Remove common punctuation and spaces
        cleaned_text = textnum.replace(',', '').replace('-', '').replace('.', '').replace(' ', '')
        # Check if the cleaned text contains only words that can be converted
        for word in cleaned_text.split():
            if word not in self.numwords and word.lower() not in self.ordinal_words:
                return False
        return True

    def _text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        """
        result = 0
        current_scale = 1
        current_position = 0

        for word in textnum.split():
            if word == 'and':
                current_scale *= 10
            elif word.lower() in self.ordinal_words:
                result += self.ordinal_words[word.lower()]
                current_position += 1
            else:
                if word in self.numwords:
                    num, pos = self.numwords[word]
                    result += num * current_scale * (10 ** pos)
                else:
                    raise ValueError(f"Invalid word: {word}")

            current_scale *= 100

        # Adjust for ordinal endings if any
        if current_position < len(self.ordinal_endings) and textnum[-len(self.ordinal_endings[current_position]):].lower() == self.ordinal_endings[current_position][0].lower():
            result -= self.ordinal_words[self.ordinal_endings[current_position][0].lower()]

        return str(result)
